import React, { useState, useEffect } from "react";
import { useParams, Link, useNavigate } from "react-router-dom";
import {
  FiArrowLeft,
  FiMapPin,
  FiPhone,
  FiMail,
  FiCheckCircle,
  FiFileText,
  FiCreditCard,
  FiShield,
  FiGlobe,
  FiAward,
  FiTag,
  FiBriefcase,
  FiCalendar,
  FiExternalLink,
  FiUser,
  FiPackage,
  FiTruck,
  FiZap,
  FiClock,
  FiCopy,
  FiEye,
  FiImage,
  FiMaximize2
} from "react-icons/fi";
import toast from "react-hot-toast";
import {
  FaFacebookF,
  FaTwitter,
  FaLinkedinIn,
  FaInstagram,
  FaYoutube,
  FaStar,
  FaRegStar,
  FaStarHalfAlt,
} from "react-icons/fa";

const SellerDetails = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [seller, setSeller] = useState(null);
  const [loading, setLoading] = useState(true);
  const [mainTab, setMainTab] = useState("about"); // "about" | "gallery" | "reviews"
  const [previewGalleryImage, setPreviewGalleryImage] = useState(null);
  const [reviewsData, setReviewsData] = useState({
    reviews: [],
    stats: { totalReviews: 0, averageRating: 0, breakdown: { 5: 0, 4: 0, 3: 0, 2: 0, 1: 0 } },
  });
  const [reviewsLoading, setReviewsLoading] = useState(false);

  const fetchReviews = async (sellerIdToFetch) => {
    if (!sellerIdToFetch) return;
    try {
      setReviewsLoading(true);
      const baseURL = process.env.REACT_APP_BACKEND_URL || "http://localhost:5001";
      const res = await fetch(`${baseURL}/api/sellers/${sellerIdToFetch}/reviews`);
      const data = await res.json();
      if (data.success && data.data) {
        setReviewsData(data.data);
      }
    } catch (err) {
      console.error("Error fetching seller reviews:", err);
    } finally {
      setReviewsLoading(false);
    }
  };

  useEffect(() => {
    window.scrollTo({
      top: 0,
      left: 0,
      behavior: "auto",
    });
  }, [id]);

  useEffect(() => {
    const fetchSeller = async () => {
      if (!id) return;
      setLoading(true);
      try {
        const baseURL = process.env.REACT_APP_BACKEND_URL || "http://localhost:5001";
        const res = await fetch(`${baseURL}/api/sellers/${id}`);
        const data = await res.json();
        if (data.success && (data.seller || data.data)) {
          const sellerObj = data.seller || data.data;
          setSeller(sellerObj);
          fetchReviews(sellerObj._id || id);
        } else {
          toast.error(data.message || "Failed to load seller details");
        }
      } catch (err) {
        console.error("Error fetching seller details:", err);
        toast.error("Error connecting to server for seller details");
      } finally {
        setLoading(false);
      }
    };

    fetchSeller();
  }, [id]);

  if (loading) {
    return (
      <div className="py-5 text-center my-5">
        <div className="spinner-border" role="status" style={{ color: "#A847F0", width: "3.5rem", height: "3.5rem" }}>
          <span className="visually-hidden">Loading seller profile...</span>
        </div>
        <h5 className="fw-800 text-dark mt-4 font-outfit">Loading Verified Seller Profile...</h5>
        <p className="text-muted" style={{ fontSize: "14px" }}>Fetching licensed distributor credentials and category approvals...</p>
      </div>
    );
  }

  if (!seller) {
    return (
      <div className="container py-5 text-center my-5">
        <div className="bg-white rounded-4 p-5 border shadow-sm max-w-lg mx-auto" style={{ borderRadius: "24px" }}>
          <FiBriefcase size={54} className="text-muted mb-3" style={{ opacity: 0.4 }} />
          <h4 className="fw-800 text-dark mb-2 font-outfit">Seller Profile Not Found</h4>
          <p className="text-muted mb-4" style={{ fontSize: "14px" }}>We couldn't retrieve profile information for this vendor.</p>
          <Link to="/all-sellers" className="btn text-white fw-700 px-4 py-2.5 shadow-sm" style={{ backgroundColor: "#A847F0", borderRadius: "30px" }}>
            <FiArrowLeft className="me-1.5" /> Back to All Sellers
          </Link>
        </div>
      </div>
    );
  }

  // Extract info
  const shopName = seller.basicInformation?.shopName || seller.shopName || "Verified Pharmacy Vendor";
  const contactPerson = seller.basicInformation?.contactPersonName || "Licensed Representative";
  const aboutSeller = seller.basicInformation?.aboutSeller || "";
  const panNumber = seller.basicInformation?.panNumber || "N/A";
  const gstin = seller.basicInformation?.gstin || "N/A";
  const bankName = seller.basicInformation?.bankName || "N/A";
  const accountNumber = seller.basicInformation?.accountNumber || "N/A";
  const ifscCode = seller.basicInformation?.ifscCode || "N/A";
  const accountHolder = seller.basicInformation?.accountHolderName || "N/A";

  const email = seller.contactInformation?.emailAddress || seller.email || "N/A";
  const phone = seller.contactInformation?.Mobileprimary || seller.phone || "N/A";
  const altPhone = seller.contactInformation?.MobileSecondary || "";
  const addressLine1 = seller.basicInformation?.addressLine1 || seller.contactInformation?.addressLine1 || "";
  const addressLine2 = seller.basicInformation?.addressLine2 || seller.contactInformation?.addressLine2 || "";
  const city = seller.basicInformation?.city || seller.contactInformation?.city || "";
  const state = seller.basicInformation?.state || seller.contactInformation?.state || "";
  const pincode = seller.basicInformation?.pincode || seller.contactInformation?.pincode || "";
  const fullAddress = [addressLine1, addressLine2, city, pincode].filter(Boolean).join(", ") || "Address not provided";

  const categoryDocs = seller.categoryDocuments || {};
  const documents = seller.documents || {};
  const social = seller.socialMediaLinks || {};

  const categoryMap = [
    { key: "medicines", label: "Medicines & Cosmetics", icon: FiPackage },
    { key: "medicalDevicesAndSurgicalEquipment", label: "Medical Devices & Surgical Equipment", icon: FiZap },
    { key: "skinAndHairCare", label: "Skin & Hair Care", icon: FiTag },
    { key: "healthSupplements", label: "Health Supplements", icon: FiAward },
    { key: "petCare", label: "Pet Care", icon: FiShield },
    { key: "veterinaryProducts", label: "Pet Care", icon: FiShield },
  ];

  const seenCats = new Set();
  const approvedCategories = categoryMap.filter((c) => {
    const isApproved = categoryDocs[c.key] && categoryDocs[c.key].status === "Approved";
    if (isApproved && !seenCats.has(c.label)) {
      seenCats.add(c.label);
      return true;
    }
    return false;
  });

  const getDocUrl = (pathVal) => {
    if (!pathVal) return null;
    let pathStr = "";
    if (typeof pathVal === "string") {
      pathStr = pathVal;
    } else if (typeof pathVal === "object" && pathVal !== null) {
      pathStr = pathVal.documentUrl || pathVal.url || pathVal.path || pathVal.location || "";
    } else {
      pathStr = String(pathVal);
    }
    if (!pathStr) return null;

    const uploadsIdx = pathStr.indexOf("uploads/");
    if (uploadsIdx !== -1) {
      pathStr = pathStr.substring(uploadsIdx);
    } else if (pathStr.startsWith("http")) {
      return pathStr;
    }

    const baseURL = process.env.REACT_APP_BACKEND_URL || "http://localhost:5001";
    const cleanPath = pathStr.startsWith("/") ? pathStr : `/${pathStr}`;
    return `${baseURL}${cleanPath}`;
  };

  const renderStarRating = (score, starSize = 16) => {
    const stars = [];
    const rounded = Math.round((Number(score) || 0) * 2) / 2;
    for (let i = 1; i <= 5; i++) {
      if (rounded >= i) {
        stars.push(<FaStar key={i} size={starSize} color="#F59E0B" />);
      } else if (rounded >= i - 0.5) {
        stars.push(<FaStarHalfAlt key={i} size={starSize} color="#F59E0B" />);
      } else {
        stars.push(<FaRegStar key={i} size={starSize} color="#CBD5E1" />);
      }
    }
    return <div className="d-inline-flex align-items-center gap-1">{stars}</div>;
  };

  return (
    <div className="seller-details-page-wrapper" style={{ backgroundColor: "#F8FAFC" }}>
      {/* 1. HERO HEADER BANNER WITH TAB BORDERED */}
      <section
        className="breadcrumb-three section-bg position-relative z-index-1 overflow-hidden"
        style={{
          paddingTop: "24px",
          paddingBottom: "0px",
        }}
      >
        <img
          src="/assets/images/gradients/Bg.png"
          alt=""
          className="bg--gradient"
          loading="lazy"
        />

        <div className="container container-two">
          {/* Back Button */}
          <div className="mb-3">
            <button
              type="button"
              onClick={() => navigate(-1)}
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: "6px",
                backgroundColor: "#ffffff",
                color: "#0F172A",
                border: "1px solid #CBD5E1",
                borderRadius: "20px",
                padding: "6px 14px",
                fontSize: "13px",
                fontWeight: "700",
                cursor: "pointer",
                boxShadow: "0 1px 4px rgba(0,0,0,0.08)",
                zIndex: 10,
                position: "relative",
              }}
            >
              <FiArrowLeft size={16} style={{ color: "#0F172A", strokeWidth: 2.5 }} />
              <span style={{ color: "#0F172A", fontWeight: 700, fontSize: "13px" }}>Back</span>
            </button>
          </div>

          {/* Seller Profile Main Info - Vertically Centered */}
          <div className="row align-items-center gy-3 pb-3">
            <div className="col-auto">
              <div className="position-relative">
                <div
                  className="d-flex align-items-center justify-content-center text-white fw-800 rounded-4 shadow-sm font-outfit overflow-hidden"
                  style={{
                    width: "88px",
                    height: "88px",
                    fontSize: "36px",
                    background: "linear-gradient(135deg, #715DF2 0%, #A847F0 100%)",
                    border: "2px solid #ffffff",
                  }}
                >
                  {(seller.basicInformation?.logo || seller.logo) ? (
                    <img
                      src={getDocUrl(seller.basicInformation?.logo || seller.logo)}
                      alt={shopName}
                      className="w-100 h-100"
                      style={{ objectFit: "cover" }}
                      onError={(e) => {
                        e.target.onerror = null;
                        e.target.style.display = "none";
                      }}
                    />
                  ) : (
                    shopName.charAt(0).toUpperCase()
                  )}
                </div>
               
              </div>
            </div>

            <div className="col">
              <div className="d-flex align-items-center gap-3 flex-wrap mb-1">
                <h2 className="fw-800 mb-0 font-outfit" style={{ fontSize: "24px", letterSpacing: "-0.5px", color: "#0F172A" }}>
                  {shopName}
                </h2>
                {reviewsData.stats?.totalReviews > 0 && (
                  <div
                    className="d-inline-flex align-items-center rounded-pill shadow-sm"
                    style={{
                      backgroundColor: "#FEF3C7",
                      border: "1px solid #FDE68A",
                      cursor: "pointer",
                      padding: "4px 12px",
                      gap: "6px",
                      transition: "transform 0.15s ease"
                    }}
                    onClick={() => setMainTab("reviews")}
                    title="View Customer Ratings & Reviews"
                  >
                    <FaStar size={13} color="#F59E0B" />
                    <span className="fw-800 text-dark" style={{ fontSize: "13px" }}>
                      {reviewsData.stats.averageRating}
                    </span>
                    <span className="text-muted" style={{ fontSize: "12px", fontWeight: "500", marginLeft: "2px" }}>
                      ({reviewsData.stats.totalReviews} {reviewsData.stats.totalReviews === 1 ? "review" : "reviews"})
                    </span>
                  </div>
                )}
              </div>

              <p className="text-secondary fw-600 mb-2" style={{ fontSize: "13.5px" }}>
                Contact Representative: <span className="text-dark fw-700">{contactPerson}</span>
              </p>

              {/* Quick Info Badges Bar */}
              <div className="d-flex flex-wrap align-items-center text-secondary" style={{ fontSize: "13px", gap: "14px" }}>
                <span className="d-inline-flex align-items-center text-secondary" style={{ gap: "8px" }}>
                  <FiMapPin size={15} style={{ color: "#715DF2", flexShrink: 0 }} />
                  <span>{city || state ? `${city}, ${state}` : "Location Available"}</span>
                </span>
                <span className="d-inline-flex align-items-center text-secondary" style={{ gap: "8px" }}>
                  <FiPhone size={15} style={{ color: "#715DF2", flexShrink: 0 }} />
                  <span>{phone}</span>
                </span>
                <span className="d-inline-flex align-items-center text-secondary" style={{ gap: "8px" }}>
                  <FiMail size={15} style={{ color: "#715DF2", flexShrink: 0 }} />
                  <span className="text-break">{email}</span>
                </span>
              </div>
            </div>
          </div>

          {/* 2. HORIZONTAL TAB NAVIGATION */}
          <ul
            className="nav tab-bordered nav-pills mt-3"
            id="pills-tabbs"
            role="tablist"
            style={{ marginBottom: "16px" }}
          >
            <li className="nav-item" role="presentation">
              <button
                className={`nav-link ${mainTab === "about" ? "active" : ""}`}
                id="pills-about-tab"
                type="button"
                role="tab"
                aria-selected={mainTab === "about"}
                onClick={() => setMainTab("about")}
              >
                About
              </button>
            </li>

            <li className="nav-item" role="presentation">
              <button
                className={`nav-link ${mainTab === "gallery" ? "active" : ""}`}
                id="pills-gallery-tab"
                type="button"
                role="tab"
                aria-selected={mainTab === "gallery"}
                onClick={() => setMainTab("gallery")}
              >
                Gallery
              </button>
            </li>

            <li className="nav-item" role="presentation">
              <button
                className={`nav-link ${mainTab === "reviews" ? "active" : ""}`}
                id="pills-reviews-tab"
                type="button"
                role="tab"
                aria-selected={mainTab === "reviews"}
                onClick={() => setMainTab("reviews")}
              >
                Ratings &amp; Reviews
              </button>
            </li>
          </ul>
        </div>
      </section>

      {/* 3. MAIN TAB CONTENT AREA */}
      <div className="container container-two pt-3 pb-5 mb-4" style={{ paddingBottom: "48px" }}>
        {mainTab === "about" ? (
          /* ======================================================== */
          /* TAB 1: ABOUT SELLER                                      */
          /* ======================================================== */
          <div className="row g-4 mb-0">
            {/* Left Column - Details */}
            <div className="col-lg-8">
              {/* About Business */}
              <div className="mb-5">
                <h4 className="fw-800 text-dark mb-3 font-outfit" style={{ fontSize: "20px", color: "#0F172A" }}>
                  About Seller
                </h4>
                <p className="text-secondary fw-500 mb-4" style={{ fontSize: "14.5px", lineHeight: "1.75" }}>
                  {aboutSeller || `${shopName} is an authorized distributor of pharmaceutical products, surgical instruments, and medical consumables. Fully compliant with state and national drug control protocols to guarantee clinical standards and product integrity.`}
                </p>

                {/* Show GST & PAN only if they are present and valid */}
                {((gstin && gstin !== "N/A" && gstin !== "") || (panNumber && panNumber !== "N/A" && panNumber !== "")) && (
                  <div className="row g-3 text-secondary" style={{ fontSize: "14.5px" }}>
                    {gstin && gstin !== "N/A" && gstin !== "" && (
                      <div className="col-sm-6">
                        <span className="text-muted fw-700 d-block mb-1" style={{ fontSize: "11px", textTransform: "uppercase", letterSpacing: "0.5px" }}>
                          GSTIN Number
                        </span>
                        <span className="text-dark fw-700">{gstin}</span>
                      </div>
                    )}
                    {panNumber && panNumber !== "N/A" && panNumber !== "" && (
                      <div className="col-sm-6">
                        <span className="text-muted fw-700 d-block mb-1" style={{ fontSize: "11px", textTransform: "uppercase", letterSpacing: "0.5px" }}>
                          PAN Number
                        </span>
                        <span className="text-dark fw-700">{panNumber}</span>
                      </div>
                    )}
                  </div>
                )}
              </div>

              {/* Contact Details */}
              <div className="mb-5">
                <h4 className="fw-800 text-dark mb-3 font-outfit" style={{ fontSize: "20px", color: "#0F172A" }}>
                  Contact Information
                </h4>
                <div className="row g-4">
                  <div className="col-sm-6">
                    <span className="text-muted fw-700 d-block mb-1" style={{ fontSize: "11px", textTransform: "uppercase", letterSpacing: "0.5px" }}>
                      Email Address
                    </span>
                    <span className="text-dark fw-700 text-break" style={{ fontSize: "15px" }}>
                      {email}
                    </span>
                  </div>
                  <div className="col-sm-6">
                    <span className="text-muted fw-700 d-block mb-1" style={{ fontSize: "11px", textTransform: "uppercase", letterSpacing: "0.5px" }}>
                      Primary Phone
                    </span>
                    <span className="text-dark fw-700" style={{ fontSize: "15px" }}>
                      {phone}
                    </span>
                  </div>
                  {altPhone && (
                    <div className="col-sm-6">
                      <span className="text-muted fw-700 d-block mb-1" style={{ fontSize: "11px", textTransform: "uppercase", letterSpacing: "0.5px" }}>
                        Secondary Phone
                      </span>
                      <span className="text-dark fw-700" style={{ fontSize: "15px" }}>
                        {altPhone}
                      </span>
                    </div>
                  )}
                </div>
              </div>

              {/* Documents Section */}
              <div className="mb-0">
                <h4 className="fw-800 text-dark mb-3 font-outfit" style={{ fontSize: "20px", color: "#0F172A" }}>
                  Documents
                </h4>
                {(() => {
                  const categoryDocsMap = {};

                  categoryMap.forEach((cat) => {
                    const docObj = categoryDocs[cat.key] || {};
                    const catApproved = docObj.status === "Approved";
                    const approvedDocs = (docObj.documents || []).filter(
                      d => d.status === "Approved" || catApproved
                    );
                    const validUrls = approvedDocs
                      .map(d => getDocUrl(d))
                      .filter(Boolean);

                    if (validUrls.length > 0) {
                      if (!categoryDocsMap[cat.label]) {
                        categoryDocsMap[cat.label] = [];
                      }
                      validUrls.forEach((u) => {
                        if (!categoryDocsMap[cat.label].includes(u)) {
                          categoryDocsMap[cat.label].push(u);
                        }
                      });
                    }
                  });

                  if (Array.isArray(documents)) {
                    const genUrls = documents
                      .filter(d => d.status === "Approved")
                      .map(d => getDocUrl(d))
                      .filter(Boolean);
                    if (genUrls.length > 0) {
                      if (!categoryDocsMap["General Documents"]) {
                        categoryDocsMap["General Documents"] = [];
                      }
                      genUrls.forEach((u) => {
                        if (!categoryDocsMap["General Documents"].includes(u)) {
                          categoryDocsMap["General Documents"].push(u);
                        }
                      });
                    }
                  }

                  const categoryDocsList = Object.entries(categoryDocsMap).map(
                    ([categoryName, urls]) => ({ categoryName, urls })
                  );

                  if (categoryDocsList.length === 0) {
                    return (
                      <p className="text-secondary fw-500 mb-0" style={{ fontSize: "14.5px" }}>
                        No approved documents found.
                      </p>
                    );
                  }

                  return (
                    <div className="d-flex flex-column gap-4">
                      {categoryDocsList.map((item, idx) => (
                        <div key={idx}>
                          <div className="fw-700 text-dark font-outfit mb-2.5" style={{ fontSize: "14.5px" }}>
                            {item.categoryName}
                          </div>
                          <div className="d-flex flex-wrap align-items-center gap-3">
                            {item.urls.map((url, uIdx) => (
                              <a
                                key={uIdx}
                                href={url}
                                target="_blank"
                                rel="noreferrer"
                                className="btn btn-sm btn-white border fw-700 py-2 px-3.5 d-inline-flex align-items-center gap-2 shadow-sm"
                                style={{
                                  fontSize: "13px",
                                  borderRadius: "8px",
                                  color: "#715DF2",
                                  borderColor: "#E2E8F0",
                                  backgroundColor: "#FFFFFF"
                                }}
                              >
                                <FiFileText size={15} /> View Document
                              </a>
                            ))}
                          </div>
                        </div>
                      ))}
                    </div>
                  );
                })()}
              </div>

            </div> {/* Closes Left Column */}

            {/* Right Column - Address and Social Cards */}
            <div className="col-lg-4">
              <div className="profile-sidebar">
                {/* Address Sidebar Item */}
                <div className="profile-sidebar__item address-sidebar-item">
                  <h5 style={{ fontWeight: "700", marginBottom: "6px", fontSize: "16px" }}>Address</h5>
                  <span style={{ color: "#1E293B", fontSize: "14px", fontWeight: "500", lineHeight: "1.5" }}>
                    {fullAddress}
                  </span>
                </div>

                {/* Social Profile Sidebar Item */}
                <div className="profile-sidebar__item seller-social-profile-card">
                  <h5 className="profile-sidebar__title">Social Profile</h5>

                  {/* Social Icons List */}
                  {((social.facebookUrl || social.facebook) ||
                    (social.instagramUrl || social.instagram) ||
                    (social.linkedInUrl || social.linkedin) ||
                    (social.twitterUrl || social.twitter) ||
                    (social.youtubeUrl || social.youtube)) ? (
                    <ul className="social-icon-list mb-3">
                      {[
                        {
                          icon: FaFacebookF,
                          key: "facebook",
                          url: social.facebookUrl || social.facebook,
                        },
                        {
                          icon: FaTwitter,
                          key: "twitter",
                          url: social.twitterUrl || social.twitter,
                        },
                        {
                          icon: FaLinkedinIn,
                          key: "linkedin",
                          url: social.linkedInUrl || social.linkedin,
                        },
                        {
                          icon: FaInstagram,
                          key: "instagram",
                          url: social.instagramUrl || social.instagram,
                        },
                        {
                          icon: FaYoutube,
                          key: "youtube",
                          url: social.youtubeUrl || social.youtube,
                        },
                      ].map(({ icon: Icon, key, url }) => {
                        if (!url || url === "") return null;
                        return (
                          <li key={key} className="social-icon-list__item">
                            <a
                              href={url}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="social-icon-list__link flx-center bg-white border-white text-heading font-18"
                            >
                              <Icon />
                            </a>
                          </li>
                        );
                      })}
                    </ul>
                  ) : null}

                  {/* Google Maps Iframe */}
                  {fullAddress && fullAddress !== "Address not provided" && (
                    <div
                      className="seller-map-wrapper"
                      style={{
                        marginTop: "14px",
                        width: "100%",
                        height: "180px",
                        borderRadius: "8px",
                        overflow: "hidden",
                        boxShadow: "0 4px 12px rgba(0,0,0,0.15)",
                        marginBottom: "0px",
                      }}
                    >
                      <iframe
                        title="Google Map"
                        width="100%"
                        height="180"
                        style={{ border: 0, display: "block" }}
                        loading="lazy"
                        allowFullScreen
                        src={`https://maps.google.com/maps?q=${encodeURIComponent(fullAddress)}&t=&z=13&ie=UTF8&iwloc=&output=embed`}
                      ></iframe>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        ) : mainTab === "gallery" ? (
          /* ======================================================== */
          /* TAB 2: SELLER GALLERY                                    */
          /* ======================================================== */
          <div className="seller-gallery-view py-2 mb-0">
            {(!seller.gallery || seller.gallery.length === 0) ? (
              <div className="text-center py-5 my-3 bg-white rounded-4 border shadow-sm p-4" style={{ borderRadius: "20px" }}>
                <div
                  className="d-flex align-items-center justify-content-center mx-auto mb-3 rounded-circle"
                  style={{ width: "64px", height: "64px", backgroundColor: "#F1F5F9", color: "#94A3B8" }}
                >
                  <FiImage size={30} />
                </div>
                <h6 className="fw-800 text-dark mb-1">No Gallery Images Available</h6>
                <p className="text-muted small mb-0">
                  This seller has not uploaded any gallery images yet.
                </p>
              </div>
            ) : (
              <div className="row g-3 row-cols-2 row-cols-sm-3 row-cols-md-4 row-cols-lg-5 row-cols-xl-5">
                {seller.gallery.map((image, index) => {
                  const rawUrl = typeof image === "string" ? image : image?.url;
                  const imgUrl = getDocUrl(rawUrl);
                  const imgName = typeof image === "string"
                    ? (image.split("/").pop() || `Gallery Image ${index + 1}`)
                    : (image?.name || image?.url?.split("/").pop() || `Gallery Image ${index + 1}`);

                  return (
                    <div key={image?._id || index} className="col">
                      <div
                        className="gallery-direct-img-wrapper position-relative overflow-hidden cursor-pointer"
                        style={{
                          height: "175px",
                          borderRadius: "14px",
                          backgroundColor: "#F8FAFC",
                          boxShadow: "0 4px 12px rgba(0,0,0,0.06)",
                          border: "1px solid rgba(0,0,0,0.06)",
                          transition: "all 0.25s ease"
                        }}
                        onClick={() => setPreviewGalleryImage({ url: imgUrl, name: imgName })}
                      >
                        <img
                          src={imgUrl}
                          alt={imgName}
                          className="w-100 h-100 gallery-direct-img"
                          style={{ objectFit: "cover", transition: "transform 0.3s ease" }}
                          onError={(e) => {
                            e.target.onerror = null;
                            e.target.src = "/assets/images/logo/BHARATLOGO-01.png";
                          }}
                        />
                        {/* Hover Overlay with Preview Icon */}
                        <div
                          className="gallery-direct-hover position-absolute top-0 start-0 w-100 h-100 d-flex align-items-center justify-content-center"
                          style={{ zIndex: 5, pointerEvents: "none" }}
                        >
                          <div
                            className="d-flex align-items-center justify-content-center shadow-lg"
                            style={{
                              width: "44px",
                              height: "44px",
                              borderRadius: "50%",
                              backgroundColor: "rgba(255, 255, 255, 0.95)",
                              color: "#0F172A",
                              border: "1px solid rgba(255, 255, 255, 0.8)",
                              transition: "transform 0.2s ease"
                            }}
                          >
                            <FiEye size={20} color="#0F172A" />
                          </div>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        ) : (
          /* ======================================================== */
          /* TAB 3: RATINGS & REVIEWS                                 */
          /* ======================================================== */
          <div className="ratings-reviews-view mb-0">
            {/* 1. Rating Summary Overview Card */}
            <div
              className="bg-white rounded-4 p-4 p-md-5 border shadow-sm mb-4"
              style={{ borderRadius: "20px" }}
            >
              <div className="row g-4 align-items-center">
                {/* Left Side: Score & Stars */}
                <div className="col-lg-4 text-center border-lg-end pb-4 pb-lg-0">
                  <div className="d-flex flex-column align-items-center justify-content-center">
                    <h1
                      className="fw-800 font-outfit mb-1"
                      style={{ fontSize: "56px", color: "#0F172A", lineHeight: 1 }}
                    >
                      {reviewsData.stats?.averageRating ? reviewsData.stats.averageRating.toFixed(1) : "0.0"}
                    </h1>
                    <div className="mb-2">
                      {renderStarRating(reviewsData.stats?.averageRating || 0, 22)}
                    </div>
                    <span className="text-muted fw-600 fs-14">
                      {reviewsData.stats?.totalReviews || 0}{" "}
                      {reviewsData.stats?.totalReviews === 1 ? "Verified Review" : "Verified Reviews"}
                    </span>
                  </div>
                </div>

                {/* Right Side: Rating Distribution Progress Bars */}
                <div className="col-lg-8 ps-lg-4">
                  <div className="d-flex flex-column gap-2.5">
                    {[5, 4, 3, 2, 1].map((star) => {
                      const count = reviewsData.stats?.breakdown?.[star] || 0;
                      const total = reviewsData.stats?.totalReviews || 0;
                      const pct = total > 0 ? Math.round((count / total) * 100) : 0;

                      return (
                        <div key={star} className="d-flex align-items-center gap-3">
                          <div className="d-flex align-items-center gap-1" style={{ width: "65px", flexShrink: 0 }}>
                            <span className="fw-700 text-dark fs-13">{star}</span>
                            <FaStar size={12} color="#F59E0B" />
                          </div>
                          <div className="progress flex-grow-1" style={{ height: "8px", backgroundColor: "#F1F5F9", borderRadius: "10px" }}>
                            <div
                              className="progress-bar"
                              role="progressbar"
                              style={{
                                width: `${pct}%`,
                                backgroundColor: star >= 4 ? "#10B981" : star === 3 ? "#F59E0B" : "#EF4444",
                                borderRadius: "10px"
                              }}
                              aria-valuenow={pct}
                              aria-valuemin="0"
                              aria-valuemax="100"
                            ></div>
                          </div>
                          <span className="text-muted fs-12 fw-600" style={{ width: "40px", textAlign: "right" }}>
                            {count}
                          </span>
                        </div>
                      );
                    })}
                  </div>
                </div>
              </div>
            </div>

            {/* 2. Customer Reviews List */}
            <div className="mb-4">
              <h4 className="fw-800 text-dark mb-4 font-outfit" style={{ fontSize: "20px" }}>
                Customer Reviews ({reviewsData.stats?.totalReviews || 0})
              </h4>

              {reviewsLoading ? (
                <div className="text-center py-4">
                  <div className="spinner-border spinner-border-sm text-primary" role="status"></div>
                  <span className="ms-2 fs-14 text-muted">Loading reviews...</span>
                </div>
              ) : reviewsData.reviews?.length > 0 ? (
                <div className="d-flex flex-column gap-3">
                  {reviewsData.reviews.map((rev) => {
                    const userObj = rev.userId || {};
                    const buyerName =
                      rev.userName ||
                      (typeof userObj === "object" && userObj !== null
                        ? (userObj.firstName
                          ? `${userObj.firstName} ${userObj.lastName || ""}`.trim()
                          : (userObj.name || userObj.fullName || ""))
                        : "") ||
                      rev.buyerName ||
                      rev.buyer?.fullName ||
                      rev.buyer?.name ||
                      "Verified Customer";
                    const reviewDate = rev.createdAt
                      ? new Date(rev.createdAt).toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" })
                      : "Recent";

                    return (
                      <div
                        key={rev._id}
                        className="bg-white rounded-4 p-4 border shadow-sm"
                        style={{ borderRadius: "16px" }}
                      >
                        <div className="d-flex justify-content-between align-items-center flex-wrap gap-2 mb-3">
                          <div>
                            <h6 className="fw-700 text-dark font-outfit mb-0" style={{ fontSize: "15px" }}>
                              {buyerName}
                            </h6>
                            <span className="text-muted fs-12">{reviewDate}</span>
                          </div>

                          {/* Stars */}
                          <div>{renderStarRating(rev.rating, 16)}</div>
                        </div>

                        {/* Review Content */}
                        {rev.review ? (
                          <p
                            className="text-secondary fw-500 mb-0"
                            style={{ fontSize: "14.5px", lineHeight: "1.65" }}
                          >
                            {rev.review}
                          </p>
                        ) : (
                          <p className="text-muted fst-italic fs-13 mb-0">
                            Rating given without comments.
                          </p>
                        )}
                      </div>
                    );
                  })}
                </div>
              ) : (
                <div
                  className="bg-white rounded-4 text-center p-5 border shadow-sm"
                  style={{ borderRadius: "20px" }}
                >
                  <div
                    className="rounded-circle d-inline-flex align-items-center justify-content-center mb-3"
                    style={{ width: "64px", height: "64px", backgroundColor: "#FAF5FF", color: "#715DF2" }}
                  >
                    <FaStar size={28} />
                  </div>
                  <h5 className="fw-800 text-dark font-outfit mb-1">No Reviews Yet</h5>
                  <p className="text-muted fs-14 mb-0" style={{ maxWidth: "420px", margin: "0 auto" }}>
                    Be the first customer to rate and review {shopName} after completing your order delivery!
                  </p>
                </div>
              )}
            </div>
          </div>
        )}
      </div>

      {/* Gallery Image Preview Lightbox Modal */}
      {previewGalleryImage && (
        <div
          style={{
            position: "fixed",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            backgroundColor: "rgba(15, 23, 42, 0.85)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            zIndex: 9999,
            padding: "16px"
          }}
          onClick={() => setPreviewGalleryImage(null)}
        >
          <div
            className="bg-white rounded-4 overflow-hidden shadow-lg"
            style={{ maxWidth: "680px", width: "100%", borderRadius: "16px" }}
            onClick={(e) => e.stopPropagation()}
          >
            <div className="d-flex align-items-center justify-content-between px-4 py-3 border-bottom bg-light">
              <div className="d-flex align-items-center gap-2">
                <FiImage size={18} color="#A847F0" />
                <span className="fw-800 text-dark" style={{ fontSize: "15px" }}>
                   Preview Image
                </span>
              </div>
              <button
                type="button"
                className="btn-close shadow-none"
                onClick={() => setPreviewGalleryImage(null)}
              ></button>
            </div>
            <div className="p-3 text-center bg-dark d-flex align-items-center justify-content-center" style={{ minHeight: "340px", maxHeight: "75vh" }}>
              <img
                src={previewGalleryImage.url}
                alt={previewGalleryImage.name || "Preview"}
                className="img-fluid rounded"
                style={{ maxHeight: "70vh", objectFit: "contain" }}
              />
            </div>
            <div className="d-flex align-items-center justify-content-between px-4 py-3 border-top bg-white">
              <a
                href={previewGalleryImage.url}
                target="_blank"
                rel="noopener noreferrer"
                className="btn btn-outline-secondary btn-sm px-3 d-inline-flex align-items-center gap-1.5"
                style={{ borderRadius: "8px", fontWeight: "600" }}
              >
                <FiMaximize2 size={14} /> Open Full Size
              </a>
              <button
                type="button"
                className="btn btn-secondary btn-sm px-4"
                style={{ borderRadius: "8px", fontWeight: "600" }}
                onClick={() => setPreviewGalleryImage(null)}
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      <style>{`
        .gallery-direct-img-wrapper {
          position: relative;
        }
        .gallery-direct-img-wrapper:hover {
          transform: translateY(-3px);
          box-shadow: 0 8px 24px rgba(168, 71, 240, 0.18) !important;
        }
        .gallery-direct-img-wrapper:hover .gallery-direct-img {
          transform: scale(1.05);
        }
        .gallery-direct-hover {
          background: rgba(15, 23, 42, 0.45);
          opacity: 0;
          transition: opacity 0.2s ease-in-out;
        }
        .gallery-direct-img-wrapper:hover .gallery-direct-hover {
          opacity: 1 !important;
        }
      `}</style>
    </div>
  );
};

export default SellerDetails;
